{"adhoc_filters": [], "applied_time_extras": {}, "click_chart_url": "https://superbi-theodoinhiemvu.hanoi.gov.vn/superset/dashboard/bcd57-l2-nv-cap-tp/?standalone=3&status_filter={status_filter}&nguon_giao={nguon_giao}&truc={truc}&van_ban_giao={van_ban_giao}&moc={moc}&from_date={from_date}&to_date={to_date}&loai_van_ban={loai_van_ban}&don_vi={don_vi}&phan_nhom_nguon={phan_nhom_nguon}&nhom_nq57={nhom_nq57}&ma_nhiem_vu={ma_nhiem_vu}", "click_chart_url_mobile": "https://superbi-theodoinhiemvu.hanoi.gov.vn/superset/dashboard/bcd57-l2-nv-cap-tp/?standalone=3&status_filter={status_filter}&nguon_giao={nguon_giao}&truc={truc}&van_ban_giao={van_ban_giao}&moc={moc}&from_date={from_date}&to_date={to_date}&loai_van_ban={loai_van_ban}&don_vi={don_vi}&phan_nhom_nguon={phan_nhom_nguon}&nhom_nq57={nhom_nq57}&ma_nhiem_vu={ma_nhiem_vu}", "datasource": "135__table", "disable_padding_default": true, "empty_content": "Không có dữ liệu", "groupby": [], "height_modal": "56", "is_hide_modal_header": true, "js_echart_building": "jsEchartScriptFunc = function (queryData, option, echarts, context) {
  /* ==========================================================================
     THẺ NGUỒN GIAO – NHIỆM VỤ TRUNG ƯƠNG – CẤP THÀNH PHỐ (Luật 1 + Luật 5)
     Bấm thẻ / thanh trạng thái / ô số → context.handleClickChart kèm nguon_giao
     của thẻ và giá trị bộ lọc đang chọn. Không có dữ liệu → nền sọc chéo, không bấm được.
     ========================================================================== */
  const elementId = context && context.elementId ? context.elementId : "bcd57-tp-ng-trung-uong";
  const width = context && context.width ? context.width : null;
  const height = context && context.height ? context.height : null;
  const rootEl = document.getElementById(elementId);
  if (!rootEl) return option;

  if (rootEl.__bcdTpNgTwCleanup) { try { rootEl.__bcdTpNgTwCleanup(); } catch (e) {} }

  // ============ 1. CẤU HÌNH ============
  // Hàng 3 chart → 12 chia hết, không dùng outerPad (Luật 6)
  const CONFIG = {
    card: {
      nguon: "tw", title: "Nhiệm vụ Trung ương", color: "#a81620",
      // số demo khi chưa có queryData
      demo: { tong: 294, dht: 189, htdh: 150, htqh: 39, dht_tronghan: 3, dht_quahan: 1, thuong_xuyen: 101, sap_den_han: 0 },
    },
    sapDenHanNgay: 7,           // số ngày cảnh báo "sắp đến hạn" (hiển thị trong tooltip)
    // Tên cột trong queryData (1 dòng tổng hợp, đã lọc theo nguồn giao của thẻ)
    cols: {
      tong: "tong", dht: "dht", htdh: "ht_dung_han", htqh: "ht_qua_han",
      dht_tronghan: "dht_tronghan", dht_quahan: "dht_quahan", thuong_xuyen: "thuong_xuyen",
      sap_den_han: "sap_den_han_ngay",
    },
  };
  const GRP = [
    { k: "dht",          s: "Đã hoàn thành", c: "#00a870" },
    { k: "dht_tronghan", s: "Trong hạn",     c: "#1b6fe3" },
    { k: "dht_quahan",   s: "Quá hạn",       c: "#e0202a" },
    { k: "thuong_xuyen", s: "Thường xuyên",  c: "#825ee4" },
  ];

  // ============ 2. DỮ LIỆU ============
  const cnt = Object.assign({ tong: 0, dht: 0, htdh: 0, htqh: 0, dht_tronghan: 0, dht_quahan: 0, thuong_xuyen: 0, sap_den_han: 0 },
    CONFIG.card.demo);
  if (queryData && queryData.data && queryData.data.length > 0) {
    const row = queryData.data[0];
    Object.keys(CONFIG.cols).forEach((k) => {
      if (row[CONFIG.cols[k]] !== undefined) cnt[k] = Number(row[CONFIG.cols[k]]) || 0;
    });
  }
  const C = CONFIG.card;
  const tong = cnt.tong;
  const base = tong - cnt.thuong_xuyen;                 // tỷ lệ hoàn thành không tính NV thường xuyên
  const dungHan = Math.max(0, cnt.dht_tronghan - cnt.sap_den_han);

  // ============ 3. HELPER ============
  const vn = (n) => Number(n).toLocaleString("vi-VN");
  const pct = (a, b) => (b ? (a * 100 / b).toFixed(1).replace(".", ",") : "0");
  const cssSize = (v) => (v == null || v === "" ? "100%" : isNaN(+v) ? String(v) : v + "px");
  const wrapId = "wrap-" + elementId;
  const tipId = "tip-" + elementId;

  // Luật 5: đọc giá trị bộ lọc tại thời điểm bấm
  function readFilters() {
    const v = (p) => { const el = document.querySelector('[id^="' + p + '"]'); return el && el.value ? el.value : ""; };
    return {
      xa_phuong: v("sel-xa-"), nguon_giao: v("sel-nguon-"), truc: v("sel-truc-"),
      van_ban_giao: v("sel-vb-"), moc: v("sel-moc-"), from_date: v("bl-from-"), to_date: v("bl-to-"),
    };
  }
  function emit(key) {
    if (context && typeof context.handleClickChart === "function") {
      context.handleClickChart(Object.assign({ status_filter: key }, readFilters(), { nguon_giao: C.nguon }));
    }
  }

  // ============ 4. CSS ============
  const styleEl = `
    <style>
      #${wrapId}{--k:${C.color};--line:#dbe4ee;--line-soft:#e9eff5;--ink:#132a45;--ink-2:#5a6b84;--ink-3:#8496ad;
        font-family:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Arial,sans-serif;box-sizing:border-box;text-align:left;}
      #${wrapId} *{box-sizing:border-box;margin:0;padding:0;}
      #${wrapId} .ngx{position:relative;height:100%;background:#fff;border:1px solid var(--line);border-radius:10px;
        box-shadow:0 1px 2px rgba(16,40,74,.06),0 6px 18px rgba(16,40,74,.07);padding:10px 14px 9px;
        display:flex;flex-direction:column;justify-content:space-between;gap:6px;overflow:hidden;cursor:pointer;
        transition:transform .14s,box-shadow .14s;}
      #${wrapId} .ngx:hover{transform:translateY(-2px);box-shadow:0 8px 24px rgba(16,40,74,.14);}
      #${wrapId} .ngx::before{content:"";position:absolute;inset:0 0 auto 0;height:4px;background:var(--k);}
      #${wrapId} .hd{display:flex;align-items:baseline;gap:12px;min-width:0;}
      #${wrapId} .nm{font-size:16px;font-weight:800;color:var(--ink);line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0;}
      #${wrapId} .v{margin-left:auto;display:flex;align-items:baseline;gap:4px;white-space:nowrap;flex:none;}
      #${wrapId} .v b{font-size:26px;font-weight:800;color:var(--k);line-height:1;font-variant-numeric:tabular-nums;letter-spacing:-.5px;}
      #${wrapId} .v small{font-size:11px;font-weight:700;color:var(--ink-3);}
      #${wrapId} .sbar{display:flex;height:15px;border-radius:6px;overflow:hidden;background:var(--line-soft);gap:2px;flex:none;}
      #${wrapId} .sbar i{display:block;height:100%;min-width:0;cursor:pointer;transition:filter .12s;}
      #${wrapId} .sbar i:hover{filter:brightness(1.12);}
      #${wrapId} .nums{display:flex;gap:7px;}
      #${wrapId} .nums span{flex:1 1 0;min-width:0;display:inline-flex;align-items:baseline;justify-content:center;gap:5px;
        font-size:11.5px;font-weight:600;line-height:1.5;color:var(--ink-2);white-space:nowrap;cursor:pointer;
        border:1px solid var(--line-soft);border-radius:7px;padding:6px 4px;background:#fff;overflow:hidden;}
      #${wrapId} .nums span:hover{border-color:#c81e28;}
      #${wrapId} .nums i{width:8px;height:8px;border-radius:2px;flex:none;align-self:center;}
      #${wrapId} .nums b{font-size:15px;font-weight:800;color:var(--ink);font-variant-numeric:tabular-nums;margin-left:1px;line-height:1.15;}
      #${wrapId} .ft{display:flex;align-items:center;gap:9px;font-size:12px;color:var(--ink-2);font-weight:600;white-space:nowrap;}
      #${wrapId} .ft .pc{font-weight:800;color:var(--ink);}
      #${wrapId} .ft .redtag{display:inline-flex;align-items:center;font-size:10.5px;font-weight:800;color:#fff;background:#e0202a;
        border-radius:999px;padding:1px 8px;}
      #${wrapId} .ft a{margin-left:auto;color:#1b6fe3;font-weight:700;cursor:pointer;}
      #${wrapId} .ft a:hover{text-decoration:underline;}
      #${wrapId} .none{font-size:12px;font-style:italic;color:var(--ink-3);font-weight:600;}
      /* Không có dữ liệu: nền sọc chéo, tắt bấm */
      #${wrapId} .ngx.empty0{background:repeating-linear-gradient(135deg,#f6f9fb 0 9px,#f1f5f9 9px 18px);cursor:default;}
      #${wrapId} .ngx.empty0:hover{transform:none;box-shadow:0 1px 2px rgba(16,40,74,.06),0 6px 18px rgba(16,40,74,.07);}
      #${wrapId} .ngx.empty0 .nums span{color:var(--ink-3);cursor:default;}
      #${wrapId} .ngx.empty0 .nums span:hover{border-color:var(--line-soft);}
      #${wrapId} .ngx.empty0 .nums i{background:#cbd5e1!important;}
      #${wrapId} .ngx.empty0 .nums b{color:var(--ink-3);}
    </style>`;

  // ============ 5. RENDER HTML ============
  const sbar = tong
    ? GRP.map((g) => (cnt[g.k] ? `<i data-st="${g.k}" style="width:${cnt[g.k] * 100 / tong}%;background:${g.c}"></i>` : "")).join("")
    : "";
  const nums = GRP.map((g) => `<span data-st="${g.k}"><i style="background:${g.c}"></i>${g.s}<b>${tong ? vn(cnt[g.k]) : "–"}</b></span>`).join("");
  const foot = tong
    ? `<div class="ft">Tỷ lệ hoàn thành <span class="pc">${pct(cnt.dht, base)}%</span>` +
      (cnt.dht_quahan ? `<span class="redtag">${vn(cnt.dht_quahan)} quá hạn</span>` : "") +
      `<a data-st="all">Xem chi tiết ›</a></div>`
    : `<div class="none">Chưa có dữ liệu</div>`;

  rootEl.innerHTML = `
    <div id="${wrapId}" style="width:${cssSize(width)};height:${cssSize(height)};">
      ${styleEl}
      <div class="ngx${tong ? "" : " empty0"}">
        <div class="hd"><div class="nm">${C.title}</div><div class="v"><b>${vn(tong)}</b><small>NV</small></div></div>
        <div class="sbar">${sbar}</div>
        <div class="nums">${nums}</div>
        ${foot}
      </div>
    </div>`;

  // Tooltip thanh trạng thái: gắn vào body để không bị khung chart cắt
  const old = document.getElementById(tipId);
  if (old) old.remove();
  const tip = document.createElement("div");
  tip.id = tipId;
