    "border-radius:8px;box-shadow:0 8px 24px rgba(16,40,74,.18);padding:8px 10px;font:11.5px 'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#132a45;";
  document.body.appendChild(tip);
  const tipHtml = () => {
    let h = `<div style="min-width:190px"><div style="font-weight:800;padding-bottom:4px;border-bottom:1px solid #eef2f7">${C.title} · ${vn(tong)} nhiệm vụ</div>`;
    GRP.forEach((g) => {
      h += `<div style="display:flex;align-items:center;gap:7px;margin-top:4px;white-space:nowrap;line-height:17px">` +
        `<i style="width:9px;height:9px;border-radius:2px;flex:none;background:${g.c}"></i><span style="color:#46566e">${g.s}:</span>` +
        `<b style="font-weight:800;margin-left:auto">${vn(cnt[g.k])}</b><span style="color:#8496ad;font-weight:600">(${pct(cnt[g.k], tong)}%)</span></div>`;
    });
    h += `<div style="margin-top:6px;padding-top:5px;border-top:1px solid #eef2f7;color:#5a6b84;font-size:11px;line-height:1.45">` +
      `Đã hoàn thành: đúng hạn ${vn(cnt.htdh)} · quá hạn ${vn(cnt.htqh)}<br>Trong hạn: còn hạn ${vn(dungHan)} · sắp đến hạn ≤ ${CONFIG.sapDenHanNgay} ngày ${vn(cnt.sap_den_han)}` +
      `<br>Bấm để xem danh sách chi tiết</div></div>`;
    return h;
  };

  // ============ 6. handleClickChart ============
  const wrapEl = document.getElementById(wrapId);
  const onClick = (e) => {
    if (!tong) return;
    const t = e.target.closest("[data-st]");
    emit(t ? t.getAttribute("data-st") : "all");
  };
  const onMove = (e) => {
    const bar = tong && e.target.closest(".sbar i");
    if (!bar) { tip.style.display = "none"; return; }
    tip.innerHTML = tipHtml();
    tip.style.display = "block";
    let x = e.clientX + 14, y = e.clientY + 14;
    if (x + tip.offsetWidth > window.innerWidth) x -= tip.offsetWidth + 28;
    if (y + tip.offsetHeight > window.innerHeight) y -= tip.offsetHeight + 28;
    tip.style.left = x + "px"; tip.style.top = y + "px";
  };
  const onLeave = () => { tip.style.display = "none"; };
  wrapEl.addEventListener("click", onClick);
  wrapEl.addEventListener("mousemove", onMove);
  wrapEl.addEventListener("mouseleave", onLeave);

  // ============ 7. CLEANUP ============
  rootEl.__bcdTpNgTwCleanup = function () {
    wrapEl.removeEventListener("click", onClick);
    wrapEl.removeEventListener("mousemove", onMove);
    wrapEl.removeEventListener("mouseleave", onLeave);
    tip.remove();
  };

  return {};
