": true, "aggregate": null, "column": null, "datasourceWarning": false, "optionName": "metric_v8n49wb3n52q"}, {"expressionType": "SQL", "label": "thuong_xuyen", "sqlExpression": "COUNT(CASE WHEN (nguon_giao = 'Nhiệm vụ Thành phố') AND ((CASE WHEN tinh_trang = 'Thường xuyên' THEN 'thuong_xuyen' WHEN tinh_trang LIKE 'Đã hoàn thành%' THEN 'dht' WHEN tinh_trang LIKE '%Quá hạn' THEN 'dht_quahan' ELSE 'dht_tronghan' END) = 'thuong_xuyen') THEN task_id END)", "hasCustomLabel": true, "aggregate": null, "column": null, "datasourceWarning": false, "optionName": "metric_ggoo1rmlah8h"}, {"expressionType": "SQL", "label": "sap_den_han", "sqlExpression": "COUNT(CASE WHEN (nguon_giao = 'Nhiệm vụ Thành phố') AND ((CASE WHEN tinh_trang = 'Thường xuyên' THEN 'thuong_xuyen' WHEN tinh_trang LIKE 'Đã hoàn thành%' THEN 'dht' WHEN tinh_trang LIKE '%Quá hạn' THEN 'dht_quahan' ELSE 'dht_tronghan' END) = 'dht_tronghan' AND COALESCE(STR_TO_DATE(han_xu_ly, '%d/%m/%Y'), STR_TO_DATE(han_xu_ly, '%Y-%m-%d')) BETWEEN DATE_FORMAT(CURDATE(), '%Y-%m-01') AND LAST_DAY(CURDATE())) THEN task_id END)", "hasCustomLabel": true, "aggregate": null, "column": null, "datasourceWarning": false, "optionName": "metric_x8x2n2lcaugq"}, {"expressionType": "SQL", "label": "sap_den_han_ngay", "sqlExpression": "COUNT(CASE WHEN (nguon_giao = 'Nhiệm vụ Thành phố') AND ((CASE WHEN tinh_trang = 'Thường xuyên' THEN 'thuong_xuyen' WHEN tinh_trang LIKE 'Đã hoàn thành%' THEN 'dht' WHEN tinh_trang LIKE '%Quá hạn' THEN 'dht_quahan' ELSE 'dht_tronghan' END) = 'dht_tronghan' AND COALESCE(STR_TO_DATE(han_xu_ly, '%d/%m/%Y'), STR_TO_DATE(han_xu_ly, '%Y-%m-%d')) BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 7 DAY)) THEN task_id END)", "hasCustomLabel": true, "aggregate": null, "column": null, "datasourceWarning": false, "optionName": "metric_nmv4matcsrh2"}]}

