  const elementId = context && context.elementId ? context.elementId : "bcd57-tp-loai-van-ban";
  const width = context && context.width ? context.width : null;
  const height = context && context.height ? context.height : null;
  const rootEl = document.getElementById(elementId);
  if (!rootEl) return option;

  if (rootEl.__bcdTpVbCleanup) { try { rootEl.__bcdTpVbCleanup(); } catch (e) {} }

  // ============ 1. CẤU HÌNH ============
  // Hàng 3 chart → 12 chia hết, không dùng outerPad (Luật 6)
  const CONFIG = {
    title: "Nhiệm vụ theo loại văn bản",
    sapDenHanNgay: 7,
    // Mỗi ô gom các giá trị cột nhóm văn bản (cols.nhom = loai_van_ban của dataset 135) vào 1 loại
    boxes: [
      { key: "ke_hoach",   t: "Kế hoạch",           ic: "cal2", m: ["Kế hoạch"] },
      { key: "tbkl",       t: "Thông báo kết luận", ic: "clip", m: ["TBKL"] },
      { key: "cong_van",   t: "Công văn",           ic: "file", m: ["Công văn"] },
      { key: "trong_tam",  t: "Nhiệm vụ trọng tâm", ic: "flag", m: ["NV trọng tâm"] },
