    // Tên cột trong queryData: mỗi dòng = 1 nhóm văn bản (đã áp bộ lọc dashboard);
    // tong_pham_vi = số NV của nhóm, chart cộng lại thành tổng phạm vi lọc
    cols: {
      nhom: "nhom_van_ban", tong: "tong", dht: "dht", htdh: "ht_dung_han", htqh: "ht_qua_han",
      dht_tronghan: "dht_tronghan", dht_quahan: "dht_quahan", thuong_xuyen: "thuong_xuyen",
      sap_den_han: "sap_den_han_ngay",
      phamVi: "tong_pham_vi",      // tổng NV trong phạm vi lọc (mọi nguồn) – hiện "x / y NV"
    },
  };
  const GRP = [
    { k: "dht",          s: "Đã hoàn thành", c: "#00a870" },
    { k: "dht_tronghan", s: "Trong hạn",     c: "#1b6fe3" },
    { k: "dht_quahan",   s: "Quá hạn",       c: "#e0202a" },
    { k: "thuong_xuyen", s: "Thường xuyên",  c: "#825ee4" },
  ];
  const NUM = ["tong", "dht", "htdh", "htqh", "dht_tronghan", "dht_quahan", "thuong_xuyen", "sap_den_han"];

  // ============ 2. DỮ LIỆU ============
  // Demo khi chưa có queryData: chưa có nhiệm vụ, phạm vi lọc 294
  let rows = [];
  let phamVi = 294;
  // Chỉ dùng queryData khi có cột nhóm văn bản (dataset tạm không có thì giữ demo); kết quả rỗng → số 0
  const hasCol = (k) => !!(queryData && ((queryData.colnames && queryData.colnames.indexOf(k) >= 0) ||
    (queryData.data && queryData.data.length > 0 && k in queryData.data[0])));
  if (hasCol(CONFIG.cols.nhom)) {
    const c = CONFIG.cols;
    phamVi = 0;
    rows = (queryData.data || []).map((r) => {
      const o = { nhom: r[c.nhom] == null ? "" : String(r[c.nhom]) };
      NUM.forEach((k) => { o[k] = Number(r[c[k]]) || 0; });
      phamVi += Number(r[c.phamVi]) || 0;
      return o;
    });
  }
  const box = CONFIG.boxes.map(() => { const o = {}; NUM.forEach((k) => { o[k] = 0; }); return o; });
  rows.forEach((r) => {
    const i = CONFIG.boxes.findIndex((b) => b.m.indexOf(r.nhom) >= 0);
    if (i >= 0) NUM.forEach((k) => { box[i][k] += r[k]; });
  });
  const shown = box.reduce((a, b) => a + b.tong, 0);

  // ============ 3. HELPER ============
  const vn = (n) => Number(n).toLocaleString("vi-VN");
