    file: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5"/></svg>',
    flag: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 21V4M5 4h11l-2 4 2 4H5"/></svg>',
  };

  // Luật 5: đọc giá trị bộ lọc tại thời điểm bấm
  function readFilters() {
    const v = (p) => { const el = document.querySelector('[id^="' + p + '"]'); return el && el.value ? el.value : ""; };
    return {
      xa_phuong: v("sel-xa-"), nguon_giao: v("sel-nguon-"), truc: v("sel-truc-"),
      van_ban_giao: v("sel-vb-"), moc: v("sel-moc-"), from_date: v("bl-from-"), to_date: v("bl-to-"),
    };
  }
  function emit(key, override) {
    if (context && typeof context.handleClickChart === "function") {
      context.handleClickChart(Object.assign({ status_filter: key }, readFilters(), override || {}));
    }
  }

  // ============ 4. CSS ============
  const styleEl = `
    <style>
      #${wrapId}{--line:#dbe4ee;--line-soft:#e9eff5;--ink:#132a45;--ink-2:#5a6b84;--ink-3:#8496ad;--panel-2:#f6f9fb;
        font-family:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Arial,sans-serif;box-sizing:border-box;text-align:left;}
      #${wrapId} *{box-sizing:border-box;margin:0;padding:0;}
      #${wrapId} .card{height:100%;background:#fff;border:1px solid var(--line);border-radius:10px;
        box-shadow:0 1px 2px rgba(16,40,74,.06),0 6px 18px rgba(16,40,74,.07);display:flex;flex-direction:column;overflow:hidden;}
      #${wrapId} .card-h{height:38px;flex:none;display:flex;align-items:center;gap:8px;padding:0 12px;background:#cedef2;border-bottom:1px solid var(--line);}
      #${wrapId} .card-h h2{font-size:11.5px;font-weight:800;letter-spacing:.55px;text-transform:uppercase;color:#1e293b;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
      #${wrapId} .card-h .ic{width:15px;height:15px;color:var(--ink-2);flex:none;display:grid;place-items:center;}
      #${wrapId} .card-h .ic svg{width:15px;height:15px;}
      #${wrapId} .card-h .note{margin-left:auto;font-size:10.5px;color:var(--ink-2);font-weight:600;white-space:nowrap;}
      #${wrapId} .card-b{flex:1;min-height:0;padding:8px 10px 10px;}
