  // Cây dữ liệu
  const sumOf = (list) => { const c = {}; NUM.forEach((k) => { c[k] = 0; }); list.forEach((r) => NUM.forEach((k) => { c[k] += r[k]; })); return c; };
  const node = (name, list, lv, key, f, short) => ({ name, short, list, lv, key, f, kids: [], c: sumOf(list) });
  const groupBy = (list, fn) => { const by = {}, ord = []; list.forEach((r) => { const k = fn(r); if (!by[k]) { by[k] = []; ord.push(k); } by[k].push(r); }); return { by, ord }; };
  const oneXa = () => CONFIG.cap === "xa" && !!readFilters().xa_phuong;

  function buildTree() {
    const root = node("TỔNG CỘNG", rows, 0, "__root", {});
    if (ST.view === "nq57") {
      const g1 = groupBy(rows, (r) => r.pnguon);
      g1.ord.sort((a, b) => sumOf(g1.by[b]).tong - sumOf(g1.by[a]).tong);
      g1.ord.forEach((k1) => {
        const n1 = node(k1, g1.by[k1], 1, "p-" + k1, { phan_nhom_nguon: k1 }); n1.fixed = true;
        const g2 = groupBy(g1.by[k1], (r) => r.nhom);
        g2.ord.sort((a, b) => g2.by[a][0].nhomStt - g2.by[b][0].nhomStt);
        g2.ord.forEach((k2) => n1.kids.push(node(k2, g2.by[k2], 2, "nq-" + k1 + "-" + k2, { phan_nhom_nguon: k1, nhom_nq57: k2 })));
        root.kids.push(n1);
      });
    } else if (ST.view === "flat") {
      const allXa = CONFIG.cap === "xa" && !oneXa();
      const g = groupBy(rows, (r) => (allXa ? r.xa + " › " + r.dv : r.dv));
      g.ord.forEach((k) => {
        const r0 = g.by[k][0];
        root.kids.push(node(k, g.by[k], 1, "f-" + k, allXa ? { xa_phuong: r0.xa, don_vi: r0.dv } : { don_vi: r0.dv }));
      });
    } else if (CONFIG.cap === "tp") {
      const g = groupBy(rows, (r) => r.truc);
      const ord = (k) => { const i = CONFIG.trucOrder.indexOf(k); return i < 0 ? 99 : i; };
      g.ord.sort((a, b) => ord(a) - ord(b));
      g.ord.forEach((tr) => {
        const n = node(tr, g.by[tr], 1, "tr-" + tr, { truc: tr }); n.fixed = true;
        const gd = groupBy(g.by[tr], (r) => r.dv);
        gd.ord.forEach((k) => n.kids.push(node(k, gd.by[k], 2, "dv-" + tr + "-" + k, { truc: tr, don_vi: k })));
        root.kids.push(n);
      });
    } else if (!oneXa()) {
      const gx = groupBy(rows, (r) => r.xa);
      gx.ord.forEach((x) => {
        const n = node(x, gx.by[x], 1, "xa-" + x, { xa_phuong: x });
        const gd = groupBy(gx.by[x], (r) => r.dv);
        gd.ord.forEach((k) => n.kids.push(node(k, gd.by[k], 2, "u-" + x + "-" + k, { xa_phuong: x, don_vi: k }, k.replace(/ (phường|xã) .*$/i, ""))));
        root.kids.push(n);
      });
    } else {
      const gd = groupBy(rows, (r) => r.dv);
      gd.ord.forEach((k) => root.kids.push(node(k, gd.by[k], 1, "d-" + k, { don_vi: k })));
    }
    return root;
  }
  const valOf = (c, k) => (k === "tl" ? (c.tong - c.thuong_xuyen ? c.dht / (c.tong - c.thuong_xuyen) : -1) : c[k]);
  function sortKids(n) {
    if (!(n.kids[0] && n.kids[0].fixed)) {
      n.kids.sort((a, b) => (valOf(a.c, ST.sortK) - valOf(b.c, ST.sortK)) * ST.sortD || a.name.localeCompare(b.name, "vi"));
    }
    n.kids.forEach(sortKids);
  }
  const expDefault = (n) => (ST.view === "nq57" ? n.lv === 1 : CONFIG.cap === "tp" ? n.lv === 1 : false);
  const isOpen = (n) => (ST.exp[n.key] == null ? expDefault(n) : ST.exp[n.key]);

  // ============ 4. CSS ============
  const styleEl = `
    <style>
      #${wrapId}{--line:#dbe4ee;--line-soft:#e9eff5;--ink:#132a45;--ink-2:#5a6b84;--ink-3:#8496ad;--panel-2:#f6f9fb;
        font-family:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Arial,sans-serif;box-sizing:border-box;text-align:left;}
      #${wrapId} *{box-sizing:border-box;margin:0;padding:0;}
      #${wrapId} .card{height:100%;background:#fff;border:1px solid var(--line);border-radius:10px;
        box-shadow:0 1px 2px rgba(16,40,74,.06),0 6px 18px rgba(16,40,74,.07);display:flex;flex-direction:column;overflow:hidden;}
      #${wrapId} .card-h{height:38px;flex:none;display:flex;align-items:center;gap:8px;padding:0 12px;background:#cedef2;border-bottom:1px solid var(--line);}
      #${wrapId} .card-h h2{font-size:11.5px;font-weight:800;letter-spacing:.55px;text-transform:uppercase;color:#1e293b;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
      #${wrapId} .card-h .ic{width:15px;height:15px;color:var(--ink-2);flex:none;display:grid;place-items:center;}
      #${wrapId} .card-h .ic svg{width:15px;height:15px;}
      #${wrapId} .gn{margin-left:auto;display:flex;align-items:center;gap:6px;font-size:10.5px;font-weight:700;color:var(--ink-2);white-space:nowrap;}
      #${wrapId} .gn select{height:24px;border:1px solid #a9c3e4;border-radius:6px;background:#fff;color:var(--ink);font-size:11.5px;font-weight:600;padding:0 4px;outline:none;cursor:pointer;font-family:inherit;}
      #${wrapId} .gn select:focus{border-color:#a81620;}
      #${wrapId} .card-b{flex:1;min-height:0;padding:8px 10px 10px;}
      #${wrapId} .tbl-wrap{height:100%;overflow:auto;border:1px solid var(--line-soft);border-radius:8px;}
      #${wrapId} table{width:100%;border-collapse:separate;border-spacing:0;font-size:12px;}
      #${wrapId} th{position:sticky;top:0;z-index:2;background:var(--panel-2);color:var(--ink-2);font-size:10.5px;font-weight:800;text-transform:uppercase;
        letter-spacing:.3px;padding:7px 8px;border-bottom:1px solid var(--line);text-align:center;white-space:nowrap;cursor:pointer;user-select:none;height:30px;}
      #${wrapId} th.l{text-align:left;cursor:default;}
      #${wrapId} th .arr{font-size:9px;color:#a81620;margin-left:3px;}
      #${wrapId} td{padding:6px 8px;border-bottom:1px solid var(--line-soft);text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap;color:var(--ink);}
      #${wrapId} td.l{text-align:left;overflow:hidden;text-overflow:ellipsis;max-width:0;width:100%;}
      #${wrapId} th.l{min-width:120px;}
      #${wrapId} tr.grp td{background:#fbeef0;font-weight:800;color:#8c1017;border-bottom:1px solid #f0d4d8;}
      #${wrapId} tr.grp.lv1 td{background:#f3f6fa;color:var(--ink);border-bottom:1px solid #e2eaf3;}
      #${wrapId} tr.grp td.l{cursor:pointer;}
      #${wrapId} tbody tr:first-child td{position:sticky;top:30px;z-index:1;}
      #${wrapId} tr:not(.grp):hover td{background:#f7fafc;}
      #${wrapId} td.n{cursor:pointer;font-weight:700;}
      #${wrapId} td.n:hover{text-decoration:underline;}
      #${wrapId} td.n.z{color:#c3ccd8;font-weight:500;cursor:default;text-decoration:none;}
      #${wrapId} td.qh{color:#e0202a;font-weight:800;}
      #${wrapId} td.qh.hot{background:#fdecec;}
      #${wrapId} .tw{display:flex;align-items:center;gap:5px;min-width:0;}
      #${wrapId} .cr{width:15px;height:15px;flex:none;display:grid;place-items:center;border:0;background:transparent;cursor:pointer;color:var(--ink-3);border-radius:3px;}
      #${wrapId} .cr:hover{background:#dde7f2;color:var(--ink);}
      #${wrapId} .cr svg{width:11px;height:11px;transition:transform .15s;}
      #${wrapId} .cr.open svg{transform:rotate(90deg);}
      #${wrapId} .cr.none{visibility:hidden;}
      #${wrapId} .nm{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
      #${wrapId} .kc{font-size:10px;font-weight:700;color:var(--ink-3);background:var(--line-soft);border-radius:999px;padding:0 5px;flex:none;}
      #${wrapId} .pbar{display:inline-flex;align-items:center;gap:6px;width:100%;justify-content:flex-end;}
      #${wrapId} .pbar i{display:inline-block;width:48px;height:5px;border-radius:9px;background:var(--line-soft);overflow:hidden;position:relative;}
      #${wrapId} .pbar i::after{content:"";position:absolute;inset:0 auto 0 0;width:var(--w);background:var(--pc);border-radius:9px;}
      /* Khung hẹp (< 720px): thu gọn đệm, chữ và thanh tỷ lệ */
      #${wrapId}.narrow th{font-size:9.5px;letter-spacing:0;padding:7px 4px;}
      #${wrapId}.narrow td{padding:6px 4px;font-size:11.5px;}
      #${wrapId}.narrow .pbar i{width:26px;}
      #${wrapId} .empty{padding:40px 0;text-align:center;color:#8a99ae;font-weight:700;}
    </style>`;

  // ============ 5. RENDER HTML ============
  function title() {
    if (ST.view === "nq57") return "Theo nhóm nhiệm vụ NQ57";
    if (CONFIG.cap === "tp") return "Theo đơn vị chủ trì";
    const xa = readFilters().xa_phuong;
    if (xa) return "Theo đơn vị – " + xa;
    return "Theo " + vn(new Set(rows.map((r) => r.xa)).size) + " xã/phường";
