      const caret = n.kids.length && n.lv > 0
        ? `<button class="cr${isOpen(n) ? " open" : ""}" data-i="${i}">${ICON.chevR}</button>` : `<span class="cr none"></span>`;
      let h = `<tr class="${cls}" data-i="${i}"><td class="l" style="padding-left:${8 + n.lv * 14}px" title="${esc(n.name)}">` +
        `<span class="tw">${caret}<span class="nm">${esc(n.short || n.name)}</span>${n.kids.length ? `<span class="kc">${n.kids.length}</span>` : ""}</span></td>`;
      COLS.forEach((sc) => {
        if (sc.k === "tl") {
