          h += `<td><span class="pbar">${base ? p.toFixed(1).replace(".", ",") : "0"}%<i style="--w:${p}%;--pc:${p >= 80 ? "#00a870" : p >= 60 ? "#f59e0b" : "#e0202a"}"></i></span></td>`;
