      `</tr></thead><tbody>${rowHtml(root)}${walk(root)}</tbody></table>`;
  }

  rootEl.innerHTML = `
    <div id="${wrapId}" style="width:${cssSize(width)};height:${cssSize(height)};">
      ${styleEl}
      <div class="card">
        <div class="card-h"><span class="ic">${ICON.table}</span><h2 class="ttl"></h2>
          <label class="gn">Góc nhìn:<select>${VIEWS.map((o) => `<option value="${o.v}"${o.v === ST.view ? " selected" : ""}>${o.t}</option>`).join("")}</select></label></div>
