  const tblEl = wrapEl.querySelector(".tbl-wrap");
  const selEl = wrapEl.querySelector(".gn select");
  function paint() {
    wrapEl.querySelector(".ttl").textContent = title();
    const top = tblEl.scrollTop;
    tblEl.innerHTML = tableHtml();
    tblEl.scrollTop = top;
  }
  paint();

  // ============ 6. TƯƠNG TÁC + handleClickChart ============
  const toggle = (n) => { ST.exp[n.key] = !isOpen(n); paint(); };
  const onClick = (e) => {
    const th = e.target.closest("th[data-k]");
    if (th) {
      const k = th.getAttribute("data-k");
      if (ST.sortK === k) ST.sortD = -ST.sortD; else { ST.sortK = k; ST.sortD = -1; }
      paint(); return;
    }
    const cr = e.target.closest(".cr[data-i]");
    if (cr) { toggle(flat[+cr.getAttribute("data-i")]); return; }
    const td = e.target.closest("td");
    if (!td) return;
    const n = flat[+td.parentNode.getAttribute("data-i")];
    if (!n) return;
    if (td.classList.contains("l")) { if (n.kids.length && n.lv > 0) toggle(n); return; }
    if (td.classList.contains("n") && !td.classList.contains("z")) emit(td.getAttribute("data-st"), n.f);
  };
  const onView = () => { ST.view = selEl.value; paint(); };
  wrapEl.addEventListener("click", onClick);
  selEl.addEventListener("change", onView);

  // ============ 7. CLEANUP ============
  rootEl.__bcdTpSumCleanup = function () {
    wrapEl.removeEventListener("click", onClick);
    selEl.removeEventListener("change", onView);
  };

  return {};
};
